    )
    case PlatformError(errorMessage: String
    )
    case SettingsError(errorMessage: String
    )
    case SerializationError(errorMessage: String
    )
    case InvalidUuid(errorMessage: String
    )
    case InvalidNonce(errorMessage: String
    )
    case InvalidPatch(errorMessage: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

