@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiCoreError: FfiConverterRustBuffer {
    typealias SwiftType = FfiCoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .CryptoError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 2: return .DatabaseError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 3: return .SyncError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 4: return .PlatformError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 5: return .SettingsError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 6: return .SerializationError(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidUuid(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 8: return .InvalidNonce(
            errorMessage: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InvalidPatch(
            errorMessage: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiCoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .CryptoError(errorMessage):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .DatabaseError(errorMessage):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .SyncError(errorMessage):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .PlatformError(errorMessage):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .SettingsError(errorMessage):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .SerializationError(errorMessage):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .InvalidUuid(errorMessage):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .InvalidNonce(errorMessage):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(errorMessage, into: &buf)
            
        
        case let .InvalidPatch(errorMessage):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(errorMessage, into: &buf)
            
        }
    }
